import copy
import unittest
import solution


class ApplyOverridesTests(unittest.TestCase):
    def test_replace_create_delete_ignore_in_order(self):
        base = {'keep': {'x': [1]}, 'replace': [1], 'delete': {'z': 2}}
        overrides = {'keep': Ellipsis, 'replace': {'new': [3]}, 'delete': None, 'created': [4]}
        base_before = copy.deepcopy(base)
        overrides_before = copy.deepcopy(overrides)
        result = solution.apply_overrides(base, overrides)
        self.assertEqual(result, {'keep': {'x': [1]}, 'replace': {'new': [3]}, 'created': [4]})
        self.assertEqual(base, base_before)
        self.assertEqual(overrides, overrides_before)

    def test_delete_absent_and_ellipsis_absent(self):
        self.assertEqual(solution.apply_overrides({'a': 1}, {'missing': None, 'other': Ellipsis}), {'a': 1})

    def test_empty_and_deep_copy_independence(self):
        base = {'a': [{'b': [1]}]}
        overrides = {'c': {'d': [2]}}
        result = solution.apply_overrides(base, overrides)
        result['a'][0]['b'].append(9)
        result['c']['d'].append(9)
        self.assertEqual(base, {'a': [{'b': [1]}]})
        self.assertEqual(overrides, {'c': {'d': [2]}})
        base['a'][0]['b'].append(8)
        overrides['c']['d'].append(8)
        self.assertEqual(result, {'a': [{'b': [1, 9]}], 'c': {'d': [2, 9]}})
        empty = {}
        empty_result = solution.apply_overrides(empty, {})
        self.assertEqual(empty_result, {})
        self.assertIsNot(empty_result, empty)

    def test_invalid_types(self):
        invalid = (None, [], (), 'x', 1)
        for base in invalid:
            with self.subTest(base=base):
                with self.assertRaises(TypeError):
                    solution.apply_overrides(base, {})
        for overrides in invalid:
            with self.subTest(overrides=overrides):
                with self.assertRaises(TypeError):
                    solution.apply_overrides({}, overrides)


if __name__ == '__main__':
    unittest.main()

